solution.bytevm.go:
package bytevm

import (
	"fmt"
	"strconv"
	"strings"
)

const (
	wrap     = false
	floorDiv = false
	stackMax = 8
	memSize  = 32
	callMax  = 16
	stepMax  = 500
	hasData  = false
)

const (
	oPush = iota
	oPop
	oDup
	oSwap
	oOver
	oAdd
	oSub
	oMul
	oDiv
	oMod
	oNeg
	oEq
	oLt
	oGt
	oNot
	oJmp
	oJz
	oJnz
	oCall
	oRet
	oLoad
	oStore
	oIn
	oOut
	oOutc
	oOuts
	oHalt
)

var names = [27]string{"push", "discard", "dupe", "flip", "", "add", "minus", "imul", "", "", "", "", "lt", "", "", "jmp", "jzero", "", "", "", "", "", "", "show", "", "", "halt"}

const lo, hi = -2147483648, 2147483647
const letters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"
const digs = "0123456789"

func ident(s string) bool {
	if s == "" || !strings.ContainsRune(letters, rune(s[0])) {
		return false
	}
	for _, c := range s {
		if !strings.ContainsRune(letters+digs, c) {
			return false
		}
	}
	return true
}

func toInt(t string) (int64, bool) {
	body := t
	if strings.HasPrefix(t, "-") {
		body = t[1:]
	}
	if body == "" || len(body) > 10 || strings.Trim(body, digs) != "" {
		return 0, false
	}
	v, _ := strconv.ParseInt(t, 10, 64)
	if v < lo || v > hi {
		return 0, false
	}
	return v, true
}

type instr struct {
	op  int
	arg int64
	lab string
}

type asmErr struct {
	line int
	msg  string
}

func norm(x int64) (int64, bool) {
	if x >= lo && x <= hi {
		return x, true
	}
	if !wrap {
		return 0, false
	}
	m := (x + (1 << 31)) % (1 << 32)
	if m < 0 {
		m += 1 << 32
	}
	return m - (1 << 31), true
}

func tdiv(a, b int64) int64 {
	return a / b
}

func fdiv(a, b int64) int64 {
	q := a / b
	if (a%b != 0) && ((a < 0) != (b < 0)) {
		q--
	}
	return q
}

func assemble(program string) ([]instr, map[string]int, []int64, *asmErr) {
	var prog []instr
	labels := map[string]int{}
	var data []int64
	var errs []asmErr
	type ref struct {
		line int
		lab  string
	}
	var refs []ref
	for i, raw := range strings.Split(program, "\n") {
		no := i + 1
		if k := strings.IndexByte(raw, ';'); k >= 0 {
			raw = raw[:k]
		}
		toks := strings.Fields(raw)
		if len(toks) == 0 {
			continue
		}
		label, hasLabel := "", false
		if strings.HasSuffix(toks[0], ":") {
			label, hasLabel = toks[0][:len(toks[0])-1], true
			toks = toks[1:]
			if !ident(label) {
				errs = append(errs, asmErr{no, "bad label"})
				continue
			}
		}
		if len(toks) > 0 && toks[0] == ".word" && hasData {
			var nums []int64
			ok := len(toks) > 1
			for _, t := range toks[1:] {
				v, good := toInt(t)
				if !good {
					ok = false
				}
				nums = append(nums, v)
			}
			if hasLabel || len(prog) > 0 || !ok || len(data)+len(nums) > memSize {
				errs = append(errs, asmErr{no, "bad data"})
			} else {
				data = append(data, nums...)
			}
			continue
		}
		if hasLabel {
			if _, dup := labels[label]; dup {
				errs = append(errs, asmErr{no, "duplicate label"})
				continue
			}
			labels[label] = len(prog)
		}
		if len(toks) == 0 {
			continue
		}
		op := -1
		for k, n := range names {
			if n != "" && n == toks[0] {
				op = k
			}
		}
		if op < 0 {
			errs = append(errs, asmErr{no, "unknown instruction"})
			continue
		}
		args := toks[1:]
		switch op {
		case oPush:
			var v int64
			good := false
			if len(args) == 1 {
				v, good = toInt(args[0])
			}
			if !good {
				errs = append(errs, asmErr{no, "bad operand"})
				continue
			}
			prog = append(prog, instr{op: op, arg: v})
		case oJmp, oJz, oJnz, oCall:
			if len(args) != 1 || !ident(args[0]) {
				errs = append(errs, asmErr{no, "bad operand"})
				continue
			}
			refs = append(refs, ref{no, args[0]})
			prog = append(prog, instr{op: op, lab: args[0]})
		default:
			if len(args) > 0 {
				errs = append(errs, asmErr{no, "bad operand"})
				continue
			}
			prog = append(prog, instr{op: op})
		}
	}
	for _, r := range refs {
		if _, ok := labels[r.lab]; !ok {
			errs = append(errs, asmErr{r.line, "unknown label"})
		}
	}
	if len(errs) == 0 {
		return prog, labels, data, nil
	}
	best := errs[0]
	for _, e := range errs {
		if e.line < best.line {
			best = e
		}
	}
	return prog, labels, data, &best
}

// Run assembles and executes a program.
func Run(program, input string) string {
	prog, labels, data, aerr := assemble(program)
	if aerr != nil {
		return fmt.Sprintf("error: line %d: %s", aerr.line, aerr.msg)
	}
	mem := make([]int64, memSize)
	copy(mem, data)
	toks := strings.Fields(input)
	ti := 0
	var stack []int64
	var rs []int
	var out strings.Builder
	pc, steps := 0, 0
	fail := func(code string) string {
		o := out.String()
		if o != "" && !strings.HasSuffix(o, "\n") {
			o += "\n"
		}
		return fmt.Sprintf("%serror: %s at %d", o, code, pc)
	}
	push := func(v int64) bool {
		if len(stack) >= stackMax {
			return false
		}
		stack = append(stack, v)
		return true
	}
	for pc < len(prog) {
		if steps >= stepMax {
			return fail("steps")
		}
		steps++
		in := prog[pc]
		npc := pc + 1
		need := func(n int) bool { return len(stack) >= n }
		pop := func() int64 {
			v := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			return v
		}
		halted := false
		switch in.op {
		case oPush:
			if !push(in.arg) {
				return fail("stack-overflow")
			}
		case oPop:
			if !need(1) {
				return fail("stack-underflow")
			}
			pop()
		case oDup:
			if !need(1) {
				return fail("stack-underflow")
			}
			if !push(stack[len(stack)-1]) {
				return fail("stack-overflow")
			}
		case oSwap:
			if !need(2) {
				return fail("stack-underflow")
			}
			n := len(stack)
			stack[n-1], stack[n-2] = stack[n-2], stack[n-1]
		case oOver:
			if !need(2) {
				return fail("stack-underflow")
			}
			if !push(stack[len(stack)-2]) {
				return fail("stack-overflow")
			}
		case oAdd, oSub, oMul, oDiv, oMod, oEq, oLt, oGt:
			if !need(2) {
				return fail("stack-underflow")
			}
			b := pop()
			a := pop()
			var r int64
			ok := true
			switch in.op {
			case oAdd:
				r, ok = norm(a + b)
			case oSub:
				r, ok = norm(a - b)
			case oMul:
				r, ok = norm(a * b)
			case oDiv, oMod:
				if b == 0 {
					return fail("div0")
				}
				q := tdiv(a, b)
				if floorDiv {
					q = fdiv(a, b)
				}
				if in.op == oDiv {
					r, ok = norm(q)
				} else {
					r = a - b*q
				}
			case oEq:
				if a == b {
					r = 1
				}
			case oLt:
				if a < b {
					r = 1
				}
			case oGt:
				if a > b {
					r = 1
				}
			}
			if !ok {
				return fail("overflow")
			}
			stack = append(stack, r)
		case oNeg:
			if !need(1) {
				return fail("stack-underflow")
			}
			r, ok := norm(-pop())
			if !ok {
				return fail("overflow")
			}
			stack = append(stack, r)
		case oNot:
			if !need(1) {
				return fail("stack-underflow")
			}
			if pop() == 0 {
				stack = append(stack, 1)
			} else {
				stack = append(stack, 0)
			}
		case oJmp:
			npc = labels[in.lab]
		case oJz, oJnz:
			if !need(1) {
				return fail("stack-underflow")
			}
			v := pop()
			if (v == 0) == (in.op == oJz) {
				npc = labels[in.lab]
			}
		case oCall:
			if len(rs) >= callMax {
				return fail("call-depth")
			}
			rs = append(rs, pc+1)
			npc = labels[in.lab]
		case oRet:
			if len(rs) == 0 {
				return fail("ret-empty")
			}
			npc = rs[len(rs)-1]
			rs = rs[:len(rs)-1]
		case oLoad:
			if !need(1) {
				return fail("stack-underflow")
			}
			a := pop()
			if a < 0 || a >= memSize {
				return fail("bad-address")
			}
			stack = append(stack, mem[a])
		case oStore:
			if !need(2) {
				return fail("stack-underflow")
			}
			a := pop()
			v := pop()
			if a < 0 || a >= memSize {
				return fail("bad-address")
			}
			mem[a] = v
		case oIn:
			if ti >= len(toks) {
				return fail("input")
			}
			v, good := toInt(toks[ti])
			if !good {
				return fail("input")
			}
			ti++
			if !push(v) {
				return fail("stack-overflow")
			}
		case oOut:
			if !need(1) {
				return fail("stack-underflow")
			}
			out.WriteString(strconv.FormatInt(pop(), 10) + "\n")
		case oOutc:
			if !need(1) {
				return fail("stack-underflow")
			}
			v := pop()
			if v < 1 || v > 127 {
				return fail("char")
			}
			out.WriteByte(byte(v))
		case oOuts:
			if !need(1) {
				return fail("stack-underflow")
			}
			a := pop()
			if a < 0 || a >= memSize {
				return fail("bad-address")
			}
			for mem[a] != 0 {
				if mem[a] < 0 || mem[a] > 127 {
					return fail("char")
				}
				out.WriteByte(byte(mem[a]))
				a++
				if a >= memSize {
					return fail("bad-address")
				}
			}
		case oHalt:
			halted = true
		}
		if halted {
			break
		}
		pc = npc
	}
	return out.String()
}

