        lineno++;
        char *sc = strchr(cur, ';');
        if (sc) *sc = 0;
        char *toks[512];
        int nt = split_ws(cur, toks, 512);
        if (nt > 0) {
            int start = 0;
            int has_label = 0;
            char label[64];
            const char *bad = NULL;
            if (toks[0][strlen(toks[0]) - 1] == ':') {
                has_label = 1;
                size_t ll = strlen(toks[0]) - 1;
                if (ll >= 63) ll = 63;
                memcpy(label, toks[0], ll);
                label[ll] = 0;
                start = 1;
                if (!ident(label)) bad = "bad label";
