            case POP: if (sp < 1) code = "stack-underflow"; else sp--; break;
            case DUP:
                if (sp < 1) code = "stack-underflow";
                else if (sp >= STACK_MAX) code = "stack-overflow";
                else { stack[sp] = stack[sp - 1]; sp++; }
