OPS = ["push", "pop", "dup", "swap", "over", "add", "sub", "mul", "div", "mod", "neg", "eq", "lt", "gt", "not", "jmp", "jz", "jnz",
       "call", "ret", "load", "store", "in", "out", "outc", "outs", "halt"]
NAMES = ["push", "pop", "dupe", "exch", "over", "plus", "minus", "imul", "idiv", "modulo", "ineg", "eq", "less", "gt", "inv", "br", "jz", "jnz", "call", "ret", "load", "poke", "recv", "out", "printc", "", "halt"]
WRAP = True
FLOOR = False
STACK = 8
MEM = 64
CALLS = 8
STEPS = 300
HAS_DATA = False
LET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"
DIG = "0123456789"
LO, HI = -2 ** 31, 2 ** 31 - 1


def ident(s):
    return s != "" and s[0] in LET and all(c in LET + DIG for c in s)


def to_int(t):
    body = t[1:] if t[:1] == "-" else t
    if body == "" or len(body) > 10 or any(c not in DIG for c in body):
        return None
    v = int(t)
    return v if LO <= v <= HI else None


def assemble(program):
    prog, labels, data, errs = [], {}, [], []
    refs = []
    for no, raw in enumerate(program.split("\n"), 1):
        toks = raw.split(";", 1)[0].split()
        if not toks:
            continue
        label = None
        if toks[0].endswith(":"):
            label = toks[0][:-1]
            toks = toks[1:]
            if not ident(label):
                errs.append((no, "bad label"))
                continue
        if toks and toks[0] == ".word" and HAS_DATA:
            nums = [to_int(t) for t in toks[1:]]
            if label is not None or prog or not nums or None in nums or len(data) + len(nums) > MEM:
                errs.append((no, "bad data"))
            else:
                data.extend(nums)
            continue
        if label is not None:
            if label in labels:
                errs.append((no, "duplicate label"))
                continue
            labels[label] = len(prog)
        if not toks:
            continue
        name = toks[0]
        if name not in NAMES:
            errs.append((no, "unknown instruction"))
            continue
        op = OPS[NAMES.index(name)]
        args = toks[1:]
        if op == "push":
            v = to_int(args[0]) if len(args) == 1 else None
            if v is None:
                errs.append((no, "bad operand"))
                continue
            prog.append((op, v, no))
        elif op in ("jmp", "jz", "jnz", "call"):
            if len(args) != 1 or not ident(args[0]):
                errs.append((no, "bad operand"))
                continue
            refs.append((no, args[0]))
            prog.append((op, args[0], no))
        else:
            if args:
                errs.append((no, "bad operand"))
                continue
            prog.append((op, 0, no))
    for no, lab in refs:
        if lab not in labels:
            errs.append((no, "unknown label"))
    return prog, labels, data, (min(errs) if errs else None)


def norm(x):
    if LO <= x <= HI:
        return x
    return None if not WRAP else (x + 2 ** 31) % 2 ** 32 - 2 ** 31


def tdiv(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b > 0) else -q


def run(program, inp):
    prog, labels, data, err = assemble(program)
    if err:
        return "error: line %d: %s" % err
    mem = [0] * MEM
    for i, v in enumerate(data):
        mem[i] = v
    toks = inp.split()
    ti = 0
    stack, rs, out = [], [], []
    pc = 0
    steps = 0

    def fail(code):
        o = "".join(out)
        if o and not o.endswith("\n"):
            o += "\n"
        return o + "error: %s at %d" % (code, pc)

    while pc < len(prog):
        if steps >= STEPS:
            return fail("steps")
        steps += 1
        op, arg, _ = prog[pc]
        npc = pc + 1

        def need(n):
            return len(stack) >= n

        def push(v):
            if len(stack) >= STACK:
                return False
            stack.append(v)
            return True

        if op == "push":
            if not push(arg):
                return fail("stack-overflow")
        elif op == "pop":
            if not need(1):
                return fail("stack-underflow")
            stack.pop()
        elif op == "dup":
            if not need(1):
                return fail("stack-underflow")
            if not push(stack[-1]):
                return fail("stack-overflow")
        elif op == "swap":
            if not need(2):
                return fail("stack-underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == "over":
            if not need(2):
                return fail("stack-underflow")
            if not push(stack[-2]):
                return fail("stack-overflow")
        elif op in ("add", "sub", "mul", "div", "mod", "eq", "lt", "gt"):
            if not need(2):
                return fail("stack-underflow")
            b = stack.pop()
            a = stack.pop()
            if op == "add":
                r = norm(a + b)
            elif op == "sub":
                r = norm(a - b)
            elif op == "mul":
                r = norm(a * b)
            elif op in ("div", "mod"):
                if b == 0:
                    return fail("div0")
                if op == "div":
                    r = norm(a // b if FLOOR else tdiv(a, b))
                else:
                    r = a % b if FLOOR else a - b * tdiv(a, b)
            elif op == "eq":
                r = 1 if a == b else 0
            elif op == "lt":
                r = 1 if a < b else 0
            else:
                r = 1 if a > b else 0
            if r is None:
                return fail("overflow")
            stack.append(r)
        elif op == "neg":
            if not need(1):
                return fail("stack-underflow")
            r = norm(-stack.pop())
            if r is None:
                return fail("overflow")
            stack.append(r)
        elif op == "not":
            if not need(1):
                return fail("stack-underflow")
            stack.append(1 if stack.pop() == 0 else 0)
        elif op == "jmp":
            npc = labels[arg]
        elif op in ("jz", "jnz"):
            if not need(1):
                return fail("stack-underflow")
            v = stack.pop()
            if (v == 0) == (op == "jz"):
                npc = labels[arg]
        elif op == "call":
            if len(rs) >= CALLS:
                return fail("call-depth")
            rs.append(pc + 1)
            npc = labels[arg]
        elif op == "ret":
            if not rs:
                return fail("ret-empty")
            npc = rs.pop()
        elif op == "load":
            if not need(1):
                return fail("stack-underflow")
            a = stack.pop()
            if a < 0 or a >= MEM:
                return fail("bad-address")
            stack.append(mem[a])
        elif op == "store":
            if not need(2):
                return fail("stack-underflow")
            a = stack.pop()
            v = stack.pop()
            if a < 0 or a >= MEM:
                return fail("bad-address")
            mem[a] = v
        elif op == "in":
            if ti >= len(toks) or to_int(toks[ti]) is None:
                return fail("input")
            v = to_int(toks[ti])
            ti += 1
            if not push(v):
                return fail("stack-overflow")
        elif op == "out":
            if not need(1):
                return fail("stack-underflow")
            out.append("%d\n" % stack.pop())
        elif op == "outc":
            if not need(1):
                return fail("stack-underflow")
            v = stack.pop()
            if v < 1 or v > 127:
                return fail("char")
            out.append(chr(v))
        elif op == "outs":
            if not need(1):
                return fail("stack-underflow")
            a = stack.pop()
            if a < 0 or a >= MEM:
                return fail("bad-address")
            while mem[a] != 0:
                if mem[a] < 0 or mem[a] > 127:
                    return fail("char")
                out.append(chr(mem[a]))
                a += 1
                if a >= MEM:
                    return fail("bad-address")
        elif op == "halt":
            break
        pc = npc
    return "".join(out)

